57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
66	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
67	     * and a dotted domain (e.g. {@code not-an-email}).
68	     */
69	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
70	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
71	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
72	
73	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
74	    private static final String DEFAULT_COUNTRY_CODE = "61";
75	
76	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
77	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
78	
79	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
80	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
81	
82	    private final ClinicService clinicService;
83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        List<String> missingFields = new ArrayList<>();
129	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
130	            missingFields.add("firstName");
131	        }
132	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
133	            missingFields.add("lastName");
134	        }
135	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
136	            missingFields.add("address");
137	        }
138	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
139	            missingFields.add("city");
140	        }
141	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
142	            missingFields.add("telephone");
143	        }
144	        if (!missingFields.isEmpty()) {
145	            throw new InvalidRequestException(missingFields);
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
150	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
151	        owner.setTelephone(normalizedTelephone);
152	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
153	        owner.setEmail(normalizeEmail(owner.getEmail()));
154	        // Default the (optional) registration date to the server's current date when none was supplied.
155	        if (owner.getRegistrationDate() == null) {
156	            owner.setRegistrationDate(LocalDate.now());
157	        }
158	        // Reject the request if the E.164 telephone is already used by another owner.
159	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
160	            throw new DuplicateTelephoneException(normalizedTelephone);
161	        }
162	        // Reject the request if another owner already shares the same last name and address
163	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
164	        // by setting 'sharesHousehold' true.
165	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
166	            && householdAlreadyExists(owner.getLastName(), owner.getAddress())) {
167	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
168	        }
169	        // Assign the customer code '<LAST3>-<NNNN>' before persisting.
170	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
171	        this.clinicService.saveOwner(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
