178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        currentOwner.setAddress(ownerFieldsDto.getAddress());
186	        currentOwner.setCity(ownerFieldsDto.getCity());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
189	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
190	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
191	        this.clinicService.saveOwner(currentOwner);
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
193	    }
194	
195	    /**
196	     * Generate a customer code formatted {@code <LAST3>-<NNNN>}, where {@code LAST3} is the
197	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
198	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
199	     *
200	     * @param lastName the owner's last name
201	     * @return the generated customer code
202	     */
203	    private String generateCustomerCode(String lastName) {
204	        String prefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
205	        int sequence = this.clinicService.findAllOwners().size() + 1;
206	        return String.format("%s-%04d", prefix.toUpperCase(Locale.ROOT), sequence);
207	    }
208	
209	    /**
210	     * Determine whether another owner already lives in the same household, i.e. shares both the
211	     * last name and the address with the given values when each is compared case-insensitively with
212	     * collapsed whitespace.
213	     *
214	     * @param lastName the incoming owner's last name
215	     * @param address  the incoming owner's address
216	     * @return {@code true} if an existing owner matches both fields
217	     */
218	    private boolean householdAlreadyExists(String lastName, String address) {
219	        String normalizedLastName = normalizeForComparison(lastName);
220	        String normalizedAddress = normalizeForComparison(address);
221	        return this.clinicService.findAllOwners().stream()
222	            .anyMatch(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
223	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress));
224	    }
225	
226	    /**
227	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
228	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
229	     *
230	     * @param value the raw value, may be {@code null}
231	     * @return the normalized value
232	     */
233	    private String normalizeForComparison(String value) {
234	        if (value == null) {
235	            return "";
236	        }
237	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
238	    }
239	
240	    /**
241	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
242	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
243	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
244	     * is returned lower-cased.
245	     *
246	     * @param email the raw email from the request payload, may be {@code null}
247	     * @return the lower-cased email, or {@code null} when none was provided
248	     */
249	    private String normalizeEmail(String email) {
250	        if (!StringUtils.hasText(email)) {
251	            return null;
252	        }
253	        if (!EMAIL_PATTERN.matcher(email).matches()) {
254	            throw new InvalidRequestException(List.of("email"));
255	        }
256	        return email.toLowerCase(Locale.ROOT);
257	    }
258	
259	    /**
260	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
261	     * already carries a leading '+' keeps its country code; otherwise the default country code
262	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
263	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
264	     * is thrown (mapped to 400 Bad Request).
265	     *
266	     * @param telephone the raw telephone from the request payload
267	     * @return the E.164 string (e.g. {@code +61412345678})
268	     */
269	    private String normalizeTelephone(String telephone) {
270	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
271	        String candidate;
272	        if (cleaned.startsWith("+")) {
273	            candidate = cleaned;
274	        } else {
275	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
276	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
277	        }
278	        if (!E164_PATTERN.matcher(candidate).matches()) {
279	            throw new InvalidRequestException(List.of("telephone"));
280	        }
281	        return candidate;
282	    }
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Transactional
286	    @Override
287	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner == null) {
290	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	        }
292	        this.clinicService.deleteOwner(owner);
293	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner == null) {
301	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	        }
303	        HttpHeaders headers = new HttpHeaders();
304	        Pet pet = petMapper.toPet(petFieldsDto);
305	        owner.setId(ownerId);
306	        pet.setOwner(owner);
307	        pet.getType().setName(null);
308	        this.clinicService.savePet(pet);
309	        PetDto petDto = petMapper.toPetDto(pet);
310	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
311	            .buildAndExpand(pet.getId()).toUri());
312	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
313	    }
314	
315	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
316	    @Override
317	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
318	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
319	        if (currentOwner != null) {
320	            Pet currentPet = this.clinicService.findPetById(petId);
321	            if (currentPet != null) {
322	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
323	                currentPet.setName(petFieldsDto.getName());
324	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
325	                this.clinicService.savePet(currentPet);
326	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
327	            }
328	        }
329	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
330	    }
331	
332	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
333	    @Override
334	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
335	        HttpHeaders headers = new HttpHeaders();
336	        Visit visit = visitMapper.toVisit(visitFieldsDto);
337	        Pet pet = new Pet();
338	        pet.setId(petId);
339	        visit.setPet(pet);
340	        this.clinicService.saveVisit(visit);
341	        VisitDto visitDto = visitMapper.toVisitDto(visit);
342	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
343	            .buildAndExpand(visit.getId()).toUri());
344	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
345	    }
346	
347	
348	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
349	    @Override
350	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
351	        Owner owner = this.clinicService.findOwnerById(ownerId);
352	        if (owner != null) {
353	            Pet pet = owner.getPet(petId);
354	            if (pet != null) {
355	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
356	            }
357	        }
358	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	    }
360	}
